<?php
namespace App\Core\Agents\Tools\FirstParty;use App\Core\Agents\Contracts\RiskLevel;use App\Core\Agents\Tools\Contracts\AgentTool;use App\Core\Agents\Tools\DTO\ToolExecutionResult;use App\Models\{AgentRun,Lead};
final class LeadUpsertTool implements AgentTool {public function name():string{return 'leads.upsert';}public function description():string{return 'Create or update a lead in the current Enverif workspace. Use only evidence-grounded fields.';}public function risk():RiskLevel{return RiskLevel::InternalWrite;}public function parameters():array{return ['type'=>'object','properties'=>['id'=>['type'=>'integer'],'email'=>['type'=>'string'],'first_name'=>['type'=>'string'],'last_name'=>['type'=>'string'],'title'=>['type'=>'string'],'company'=>['type'=>'string'],'website'=>['type'=>'string'],'linkedin_url'=>['type'=>'string'],'city'=>['type'=>'string'],'country'=>['type'=>'string'],'status'=>['type'=>'string'],'score'=>['type'=>'integer'],'source'=>['type'=>'string'],'source_url'=>['type'=>'string'],'research_summary'=>['type'=>'string']]];}public function execute(AgentRun $run,array $a):ToolExecutionResult{$id=$a['id']??null;unset($a['id']);$a=array_intersect_key($a,array_flip((new Lead)->getFillable()));$a['workspace_id']=$run->workspace_id;if($id){$lead=Lead::where('workspace_id',$run->workspace_id)->findOrFail($id);$lead->update($a);}else{$lead=Lead::create($a);}return ToolExecutionResult::success($lead->only(['id','first_name','last_name','email','company','status','score','source']));}}
